SPECS = {'azure.gap.compute_vm_adaptive_application_controls_enabled': {'category': 'vulnerability', 'data_source': 'Paged ARM Microsoft.Security/assessments LIST 2020-01-01 and Microsoft.Security/locations/{location}/applicationWhitelistings group inventory; properties.resourceDetails.id/status.code for assessment, group VM recommendations and allowlist policy details; paged VM inventory and stable assessment key. Join by full VM ARM ID.', 'description': 'Checks current adaptive application-control group policy and per-VM assessment health; recommendation status alone is insufficient.', 'id': 'azure.gap.compute_vm_adaptive_application_controls_enabled', 'predicate': 'For each in-scope VM, join a configured stable assessment key and properties.resourceDetails.id, then verify membership in a current Microsoft.Security/applicationWhitelistings group with a configured active allowlist/audit policy and evidence that unknown applications generate alerts. Healthy assessment alone is insufficient. FAIL on a measured Unhealthy assessment or a complete group inventory proving no active applicable policy. PASS only with measured policy, alert behavior and Healthy assessment. UNKNOWN if group applicability, group schema/availability, alert evidence, assessment key, inventory, status or policy details cannot be resolved; NotApplicable requires independently established inapplicability.', 'provider': 'azure', 'remediation_hint': 'In Defender for Cloud > Adaptive application controls, assign each applicable VM to an active application allow-list policy, configure alerts for unknown applications, and verify its recommendation becomes Healthy.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Adaptive application controls are enabled on applicable VMs'},
 'azure.gap.compute_vm_adaptive_network_hardening_recommendation_applied': {'category': 'vulnerability', 'data_source': 'Paged VM and Microsoft.Security/assessments LIST 2020-01-01 plus Microsoft.Security/adaptiveNetworkHardenings GET/LIST recommendations and effective NSG rules; stable assessment key policy. Join on full VM ARM ID.', 'description': 'Checks applied effective NSG recommendations and per-VM assessment health for applicable Internet-facing VMs.', 'id': 'azure.gap.compute_vm_adaptive_network_hardening_recommendation_applied', 'predicate': 'For each Internet-facing applicable VM, join a current adaptive network hardening assessment by stable key and properties.resourceDetails.id. Healthy is recommendation-health evidence; PASS for applied recommendations requires the corresponding approved NSG rule recommendation to be applied and effective for that VM. FAIL on a measured Unhealthy recommendation or unapplied required rule. UNKNOWN for missing assessment, recommendation rule details, VM applicability, NSG join, freshness or inventory. NotApplicable is NOT_APPLICABLE only when applicability is established.', 'provider': 'azure', 'remediation_hint': 'In Defender for Cloud > Adaptive network hardening, apply each recommended NSG rule for affected Internet-facing VMs and verify effective rules and assessment health.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Adaptive network hardening recommendations are applied'},
 'azure.gap.compute_vm_administrators_group_with_extra_accounts_windows': {'category': 'hardening', 'data_source': 'Collector azure.py embeds VM guestConfigurationAssignments, but no reports. NEW: for each Windows VM and matching named assignment GET {assignment-id}/reports?api-version=2024-04-05, follow nextLink; join the report by its parent assignment ARM ID, properties.assignment.name, properties.vm.id, and properties.assignment.configuration name/version. Inspect properties.details.resources and effective assignment parameters against the approved member set.', 'description': 'Remove unapproved Windows Administrators group members. A finding is raised when a current named Administrators-membership assignment reports NonCompliant against the approved member set.', 'id': 'azure.gap.compute_vm_administrators_group_with_extra_accounts_windows', 'predicate': 'For each Windows VM, PASS only if a latest fresh successful report for that exact VM and approved Administrators baseline/version has the approved member parameter set, a complete nonempty set of relevant properties.details.resources, and each relevant resource is Compliant with no unapproved member. FAIL on a fresh report identifying an unapproved member or relevant NonCompliant resource, or a complete inventory proving the required baseline absent. UNKNOWN if approved set, assignment parameters, report, freshness, result detail, or inventory is incomplete. Assignment summary alone never proves PASS.', 'provider': 'azure', 'remediation_hint': 'Azure portal > Machine configuration: assign the approved Windows Administrators membership baseline, inspect its latest report, and remove each unapproved local group member.', 'resource_kind': 'vm', 'severity': 'high', 'title': 'Remove unapproved Windows Administrators group members'},
 'azure.gap.compute_vm_administrators_group_with_no_specified_members_windows': {'category': 'hardening', 'data_source': 'Paged per-VM Guest Configuration assignment GET/LIST 2024-04-05: properties.latestReportId and assignment parameters for approved local Administrators members; GET {assignmentId}/reports/{latestReportId}: properties.details.resources[].complianceStatus/reasons. Include complete Windows VM inventory and report-age policy.', 'description': 'Checks required members of Windows local Administrators through guest configuration evidence.', 'id': 'azure.gap.compute_vm_administrators_group_with_no_specified_members_windows', 'predicate': 'For each in-scope Windows VM, PASS only if the current report for the exact membership assignment demonstrates every policy-specified required member is present. FAIL only when specific current report detail proves a required member absent. UNKNOWN for missing policy parameter, assignment, latestReportId, report detail, freshness or VM/assignment paging. Assignment-level complianceStatus alone is insufficient.', 'provider': 'azure', 'remediation_hint': 'Azure Policy > Guest Configuration: assign the approved local Administrators membership policy with expected members; add missing members on the VM and rerun the guest assignment.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Audit Windows machines missing any of specified members in the Administrators group'},
 'azure.gap.compute_vm_administrators_group_with_specified_members_windows': {'category': 'hardening', 'data_source': 'Existing azure.py Windows vm.items[] and guest_configuration_assignment.items[]; new paged assignment report GET /guestConfigurationAssignments/{name}/reports?api-version=2022-01-25 for purpose-built local Administrators membership baseline. Report must contain observed membership and assigned parameter values.', 'description': 'Uses an explicit guest configuration assignment to audit prohibited members in the local Administrators group.', 'id': 'azure.gap.compute_vm_administrators_group_with_specified_members_windows', 'predicate': 'For each Windows VM, FAIL if a current report identifies a prohibited Administrators member. PASS only if the assigned baseline is Compliant, report confirms evaluated group membership against the exact prohibitedAdministrators input, and report freshness is within policy. UNKNOWN if list, assignment, report, parameter binding or freshness is absent; never infer clean membership from missing assignment.', 'provider': 'azure', 'remediation_hint': 'Azure Policy > Guest Configuration: assign the local Administrators membership audit with prohibited principals; inspect assignment report and remove those members from each VM.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Audit Windows machines that have the specified members in the Administrators group'},
 'azure.gap.compute_vm_container_security_configurations_vulnerabilities_remediated': {'category': 'vulnerability', 'data_source': 'Collector peaso/collectors/azure.py: vm and security_assessment are collected; assessment fields are properties.resourceDetails.id, properties.status.code (Healthy/Unhealthy/NotApplicable), name (stable assessment key). Require policy set of Docker-host assessment keys, and a complete assessment page for each VM.', 'description': 'Checks Defender for Cloud Docker host configuration assessment results on VMs.', 'id': 'azure.gap.compute_vm_container_security_configurations_vulnerabilities_remediated', 'predicate': 'PASS if every VM proven to host containers has a Healthy result for every required Docker-host assessment key at that VM resource ID. FAIL if any required assessment is Unhealthy. UNKNOWN if host applicability, assessment keys, complete assessment results or VM inventory are unknown; NotApplicable is not PASS.', 'provider': 'azure', 'remediation_hint': 'Defender for Cloud > Recommendations: open each Unhealthy Docker host assessment on the VM, apply its configuration fix and rescan.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Docker host security configuration findings are resolved'},
 'azure.gap.compute_vm_malware_agent_automatic_upgrade_enabled': {'category': 'vulnerability', 'data_source': 'Paged Windows VM and antimalware-extension inventory; guest Run Command executes Get-MpComputerStatus and Get-MpPreference, and reads effective Defender signature-update policy/registry including SignatureScheduleDay and SignatureUpdateInterval. Determine whether Microsoft Defender or the Microsoft Antimalware extension is the applicable protection agent; vendor evidence is required for other agents.', 'description': 'Checks effective automatic antimalware signature-update configuration on Windows VMs.', 'id': 'azure.gap.compute_vm_malware_agent_automatic_upgrade_enabled', 'predicate': 'For each scoped Windows VM using Microsoft Defender/Microsoft Antimalware, PASS only when automatic signature updates are enabled by effective guest policy and the protection service is operational. FAIL when a complete guest read proves automatic signature updates disabled or the required agent absent/disabled. UNKNOWN for unreadable guest policy, ambiguous agent applicability, incomplete VM inventory, or a third-party agent without vendor evidence. Signature age is a health signal and must not by itself turn a configured automatic-update control into FAIL or PASS.', 'provider': 'azure', 'remediation_hint': 'On affected Windows VMs, enable Microsoft Defender Antivirus and automatic signature updates via policy, restore update source connectivity, then run Update-MpSignature and confirm Get-MpComputerStatus freshness.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Windows VM antimalware signatures update automatically'},
 'azure.gap.compute_vm_meet_firewall_properties_windows': {'category': 'network', 'data_source': 'Paged Windows VM and guestConfigurationAssignments inventory plus GET {assignment-id}/reports?api-version=2024-04-05; report properties.details.resources[].resourceId, complianceStatus, properties and reasons; policy names the required Windows Firewall Properties baseline, expected settings, assignment and report freshness.', 'description': 'Checks every required Windows Firewall Properties setting in current guest configuration reports.', 'id': 'azure.gap.compute_vm_meet_firewall_properties_windows', 'predicate': 'For each applicable Windows VM, compare every named Group Policy setting in the Windows Firewall Properties baseline, including firewall state, inbound/outbound connections, rule management and notifications, with the latest fresh report for that VM. PASS only when all required setting results are Compliant. FAIL if any required setting is explicitly NonCompliant. UNKNOWN for missing assignment/report, unmeasured settings, ambiguous resource IDs, stale report or incomplete pages. Three profile states alone cannot pass.', 'provider': 'azure', 'remediation_hint': 'Deploy the Windows Firewall Properties machine configuration assignment and remediate every reported setting for firewall state, connections, rule management and notifications; rerun the report.', 'resource_kind': 'vm', 'severity': 'high', 'title': 'Windows Firewall Properties baseline is compliant'},
 'azure.gap.compute_vm_password_file_permissions_0644_linux': {'category': 'identity', 'data_source': 'Microsoft.GuestConfiguration/guestConfigurationAssignments GET for each Linux VM: properties.complianceStatus,properties.latestReportId; GET or LIST /guestConfigurationAssignments/{assignmentName}/reports using latestReportId: properties.details.resources[].resourceId,complianceStatus,reasons. Require an assignment whose configuration explicitly checks /etc/passwd mode 0644. Read assignment/report timestamps and an approved maxReportAge; correlate latestReportId to the exact report and VM. Read assignment/report timestamps and an approved maxReportAge; correlate latestReportId to the exact report and VM.', 'description': 'Checks /etc/passwd permissions using an explicit Linux guest configuration assignment.', 'id': 'azure.gap.compute_vm_password_file_permissions_0644_linux', 'predicate': 'For each inventoried Linux VM, PASS only if the latest report matching its exact assignment and latestReportId has a file-level Compliant result explicitly proving /etc/passwd mode 0644 and is within approved maxReportAge. FAIL if a current matching report proves a different mode, or a complete current assignment inventory proves the required assignment absent. UNKNOWN if policy age, assignment identity, latestReportId, report timestamp, file-level evidence, pagination or Linux VM inventory is missing or stale. Aggregate FAIL before UNKNOWN.', 'provider': 'azure', 'remediation_hint': 'On the Linux VM run sudo chmod 0644 /etc/passwd, then rerun the Azure Machine Configuration assignment and confirm the file-level report.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Audit Linux machines that do not have the passwd file permissions set to 0644'},
 'azure.gap.compute_vm_rdp_service_disabled': {'category': 'hardening', 'data_source': 'Windows VM inventory; Guest Configuration assignment reports for TermService; time-bounded officer approval register keyed by VM ID; Windows RDP sign-in/session log routing and monitored-alert evidence for approved enabled instances.', 'description': 'Measures Windows Remote Desktop Services state through guest evidence, with time-bounded exceptions.', 'id': 'azure.gap.compute_vm_rdp_service_disabled', 'predicate': 'For every Windows VM, require a current guest report proving TermService disabled or a VM-specific current approved exception for enabled RDP. For any approved enabled RDP path, also require enabled and monitored remote-access logs as the frozen requirement states. FAIL for proved enabled RDP without approval or proved missing required logging; PASS only when all applicable service, approval and monitoring evidence is complete. UNKNOWN for absent assignment/report, stale report, exception, log-routing or monitoring evidence.', 'provider': 'azure', 'remediation_hint': 'Disable TermService unless an authorized exception is current; for exceptions, enable remote-access logs and monitored alerts.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Windows VM RDP service is disabled unless explicitly approved'},
 'azure.gap.compute_vm_remote_access_restricted_all_ports': {'category': 'hardening', 'data_source': 'Collected vm, nic, subnet and nsg items: NIC/subnet networkSecurityGroup.id and each associated NSG properties.securityRules/defaultSecurityRules (sourceAddressPrefix(es), destinationPortRange(s), protocol, access, priority).', 'description': 'Checks each VM-associated NIC and subnet NSG for effective permissive inbound rules from Any or Internet source ranges across all protocols and ports.', 'id': 'azure.gap.compute_vm_remote_access_restricted_all_ports', 'predicate': 'For each VM-associated NIC and subnet NSG independently, evaluate inbound securityRules and defaultSecurityRules in priority order. FAIL if a complete effective rule path within either associated NSG permits any inbound traffic from Any, Internet, 0.0.0.0/0 or ::/0; a deny in the other NSG does not excuse the permissive associated NSG under the frozen rule. PASS only when every associated NSG is fully resolved and none has such an effective public allow. UNKNOWN for missing associations, unresolved service tags/ASGs, rule priorities, VM/NIC/subnet joins or incomplete inventories. If a VM has no associated NSG, report that as a separate unprotected-path signal and UNKNOWN for this NSG-rule control unless the source explicitly includes absence.', 'provider': 'azure', 'remediation_hint': 'On VM NIC and subnet NSGs, remove or narrow inbound Allow rules from Any/Internet and verify effective security rules in Network Watcher.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'VM associated NSGs restrict internet ingress'},
 'azure.gap.compute_vm_system_updates_installed': {'category': 'hardening', 'data_source': 'Paged VM inventory and each VM GET 2023-09-01 with $expand=instanceView: properties.instanceView.patchStatus.availablePatchSummary.status,lastModifiedTime,criticalAndSecurityPatchCount. For PCI references, collect Azure Update Manager patch-installation compliance state and correlate the exact VM and operation.', 'description': 'Install missing security system updates. A finding is raised when a recent successful assessment has positive criticalAndSecurityPatchCount.', 'id': 'azure.gap.compute_vm_system_updates_installed', 'predicate': 'For the missing-security-updates references, PASS only on a fresh successful assessment with criticalAndSecurityPatchCount=0; FAIL on a fresh successful assessment with count>0. For PCI references, also require an exact VM post-installation COMPLIANT status; NON_COMPLIANT is FAIL. UNKNOWN if freshness threshold, status, count, PCI compliance record, VM join or inventory is missing; a zero available count alone cannot establish post-installation PCI compliance.', 'provider': 'azure', 'remediation_hint': 'Azure portal > Azure Update Manager > Machines: run a patch assessment, install Critical and Security updates, and reassess.', 'resource_kind': 'vm', 'severity': 'high', 'title': 'Install missing security system updates'},
 'azure.gap.compute_vm_tcp_udp_access_restricted_internet': {'category': 'network', 'data_source': 'Paged VM, NIC, subnet, public-IP, NSG, load-balancer and effective security rule reads; join by full ARM IDs. NSG association on NIC or subnet is the frozen requirement signal; policy prohibitedPorts is optional extra reachability analysis.', 'description': 'Checks inbound TCP/UDP exposure of public VM interfaces using attached NSG rules.', 'id': 'azure.gap.compute_vm_tcp_udp_access_restricted_internet', 'predicate': 'For each internet-facing VM NIC, PASS only if a valid NSG is attached to that NIC or its subnet, as required by the frozen rule. FAIL if complete NIC, public-IP and subnet evidence proves neither association. UNKNOWN if inventory or joins are incomplete. If policy additionally requires prohibited port analysis, evaluate effective rules and NAT separately; do not use that stricter test to change this source-rule result.', 'provider': 'azure', 'remediation_hint': 'Attach an NSG to the public VM NIC or its subnet and configure appropriate inbound restrictions; separately review NAT and effective rules for prohibited ports.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'Internet-facing VM interfaces and subnets have NSG protection'},
 'azure.gap.compute_vm_vulnerability_findings_resolved_for_sql_server': {'category': 'vulnerability', 'data_source': 'Paged Microsoft.SqlVirtualMachine/sqlVirtualMachines LIST with properties.virtualMachineResourceId; paged Microsoft.Security/assessments LIST 2020-01-01 with properties.resourceDetails.id and properties.status.code; policy stable SQL VM assessment names plus all applicable finding/subassessment identifiers; complete VM join and assessment freshness.', 'description': 'Uses Defender assessment status for SQL Server on Azure VMs.', 'id': 'azure.gap.compute_vm_vulnerability_findings_resolved_for_sql_server', 'predicate': 'For each SQL VM, FAIL if a current applicable SQL vulnerability finding or assessment joined by normalized properties.resourceDetails.id is Unhealthy. PASS only when the complete applicable finding set is resolved and current Healthy evidence covers the VM; UNKNOWN for NotApplicable, missing or stale findings, assessment-key ambiguity, SQL VM join or incomplete paging. One healthy umbrella assessment cannot prove all findings resolved.', 'provider': 'azure', 'remediation_hint': 'Defender for Cloud > Recommendations > SQL Server on machines: enable the assessment on the SQL VM and resolve every reported unhealthy finding.', 'resource_kind': 'vm', 'severity': 'medium', 'title': 'SQL Server VM vulnerability assessment is healthy'},
 'azure.gap.compute_vm_with_no_specified_certificates_in_trusted_root_windows': {'category': 'encryption', 'data_source': 'Paged Windows VM and Guest Configuration assignment LIST 2024-04-05; read assignment parameter containing required trusted-root certificate thumbprints, properties.latestReportId, then GET the corresponding assignment report with evaluated certificate-store resources and freshness. Policy requiredThumbprints and maximum report age.', 'description': 'Remove prohibited trusted-root certificates. A finding is raised when a current assignment reports a prohibited trusted-root certificate.', 'id': 'azure.gap.compute_vm_with_no_specified_certificates_in_trusted_root_windows', 'predicate': 'For each scoped Windows VM, FAIL when a current complete trusted-root report proves one or more policy-required certificates absent from LocalMachine\\Root. PASS only when the exact required thumbprint set is bound to the assignment and a current complete report proves every required certificate present. UNKNOWN when assignment, parameter binding, report, freshness, required set or pages are incomplete. Empty required set is UNKNOWN without an explicit policy decision.', 'provider': 'azure', 'remediation_hint': 'Install each policy-required trusted-root certificate in LocalMachine\\Root on the affected Windows VM, rerun the Guest Configuration assignment and verify its current report.', 'resource_kind': 'vm', 'severity': 'high', 'title': 'Ensure specified trusted-root certificates are present on Windows VMs'}}

